import { createContext } from 'react';

import type { TimeframeV2 } from '../../../../core/types/time.js';
import type {
  _CalendarState,
  _CalendarReducerAction,
} from '../types/shared-types.js';

/** @internal */
export type CalendarContextProps = {
  onChange?: (value: string | null | TimeframeV2) => void;
  state: _CalendarState;
  dispatch: React.Dispatch<_CalendarReducerAction>;
};

// Current date
const today = new Date();

export const initialState: _CalendarState = {
  activeDate: today,
  currentView: 'day',
  isCalendarBodyFocused: null,
  selectedDate: null,
  today,
  weekStartsOn: 1,
  type: 'single',
  timeOffset: 'startOfDay',
};

/** Calendar context, used to access the state and dispatcher in other components */
export const CalendarContext: React.Context<CalendarContextProps> =
  createContext<CalendarContextProps>({
    state: initialState,
    dispatch: () => null,
    onChange: () => null,
  });
